def add(proc, title, do, boss, tool):
    r = subprocess.run([PY, PROC, "add", proc, title, "--do", do, "--boss", boss, "--tool", tool, "--who", "탐"], capture_output=True, text=True, encoding="utf-8")
    out = (r.stdout.strip().splitlines() or [""])[-1] if r.returncode == 0 else ("FAIL " + (r.stderr or r.stdout)[-120:])
    print(len(do), "자 |", out[:110], flush=True)

for c in CARDS + [NEXT]:
    add(*c)
